#!/bin/bash
cd "$(dirname "$0")/../.."
node scripts/portraits/select-source.js --slug anfernee-hardaway --url 'https://cdn.nba.com/teams/legacy/www.nba.com/suns/sites/suns/files/03-triple-double-penny-hardaway.jpg' --page 'https://www.nba.com/suns/gallery/ten-best-suns-triple-doubles' --license 'unknown (NBA.com)' --author 'NBA.com' --date 'c. 2000 (Suns vs Spurs, playoff signage; undated Suns triple-doubles gallery photo)' --crop 451,1,528 --scores 2,1,3,2,2,1,0 --energy 7 --vs-mccain 'matches (looking up off-camera, mouth open mid-breath, triple-threat)' --jersey 'PHX white home sunburst, 1999-00' --concerns 'FLAG: face 199px (below 250, will be upscaled), slightly soft film scan; PHX not target ORL: no usable in-game ORL photo found on nba.com (Getty scans of 22 Magic/history pages under both names, Magic/Suns legacy pages) or Commons; photostore.nba.com ORL frames are watermarked and ~600px with tiny faces' --alt 'https://cdn.nba.com/teams/legacy/www.nba.com/magic/sites/magic/files/penny-hardaway-orlando-magic-2016.jpg (ORL pinstripe but mid-dunk, head tilted back, 154px face)' --alt 'https://cdn.nba.com/manage/2021/07/penny640.jpg (ORL pinstripe 1990s, mid-dunk, face tiny)'
node scripts/portraits/select-source.js --slug shawn-marion --url 'https://cdn.nba.com/manage/2024/12/GettyImages-52726289-scaled-e1734541109184.jpg' --page 'https://www.nba.com/news/nba-birthdays-players-born-on-may-7' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date 'April 27, 2005 (2005 West First Round Game 2 vs MEM, America West Arena)' --crop 514,0,988 --scores 2,3,3,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (looking off-camera, lips parted mid-breath, calmer brows)' --jersey 'PHX white home 2004-05 (2005 playoffs)' --concerns 'mild JPEG softness on the nba.com copy; energy at the low end of the band' --alt 'https://upload.wikimedia.org/wikipedia/commons/6/66/Shawn_Marion.jpg (PHX purple 2007, energy 7.5, but a phone-call taunt gesture with his hand beside his face inside the crop)' --alt 'https://cdn.nba.com/teams/legacy/www.nba.com/suns/sites/suns/files/shawn-marion-lead.jpg (PHX purple in-game grin, 288px but from a 777px web copy, head tilted ~25 degrees)'
node scripts/portraits/select-source.js --slug gilbert-arenas --url 'https://cdn.nba.com/manage/2023/09/GettyImages-56506677.jpg' --page 'https://www.nba.com/news/nba-birthdays-players-born-on-jan-6' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date 'December 30, 2005 (vs MIA, MCI Center)' --crop 596,24,819 --scores 2,3,3,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (driving, eyes locked off-camera, lips parted mid-breath)' --jersey 'WAS white home 2005-06' --concerns 'slight softness on the 1920px nba.com copy; energy at the low end of the band' --alt 'https://upload.wikimedia.org/wikipedia/commons/c/ce/ArenasWizards.jpg (WAS white playoff layup c. 2008, 393px, mouth open looking up, but mid-attack energy ~8 and the ball beside the crop)' --alt 'https://upload.wikimedia.org/wikipedia/commons/2/2a/Gilbert_arenas_2008.jpg (WAS white 2008, sharp 479px, but a calm free-throw-line look, energy ~5)'
# steve-francis: skipped, no usable in-game photo on nba.com or Commons
