node scripts/portraits/select-source.js --slug lamar-odom --url 'https://cdn.nba.com/manage/2024/10/GettyImages-112205386-scaled-e1730148972912.jpg' --page 'https://www.nba.com/news/nba-players-born-on-nov-6' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date 'April 13, 2011 (at SAC, Power Balance Pavilion)' --crop 862,7,850 --scores 3,3,3,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (glancing just off-camera, lips parted in a half-smile mid-breath)' --jersey 'LAL purple road 2010-11 (Sixth Man of the Year season)' --concerns 'none (energy at the low end of the band; slight smile)' --alt 'https://upload.wikimedia.org/wikipedia/commons/3/3a/LamarOdom.jpg (LAL purple 2007, 305px, arguing a call with arm out, energy ~8, Bynum’s face behind him in the crop)' --alt 'https://upload.wikimedia.org/wikipedia/commons/7/7d/LakersSpurs0693.jpg (LAL 2007, 141px, too small)'
node scripts/portraits/select-source.js --slug deron-williams --url 'https://upload.wikimedia.org/wikipedia/commons/a/ab/Deron_Williams_2008.jpg' --page 'https://commons.wikimedia.org/wiki/File:Deron_Williams_2008.jpg' --license 'CC BY 2.0' --author 'Stephanie Young Merzel' --date '2007-08 (Commons caption; vs LAL at Utah, likely the 2008 West Semifinals)' --crop 878,334,933 --scores 2,3,3,2,2,2,1 --energy 6 --vs-mccain 'slightly lower (eyes just off-camera, lips parted mid-breath during a stoppage)' --jersey 'UTA white home 2007-08' --concerns 'Flickr fan photo, mildly soft; Derek Fisher in the frame but outside the crop' --alt 'https://upload.wikimedia.org/wikipedia/commons/5/54/Default_Flickr-Dateiname_%282485884604%29.jpg (same game set, UTA white, mouth open talking, energy ~6.5, but heavy-lidded eyes and a busy crowd behind, 291px)' --alt 'https://cdn.nba.com/teams/uploads/sites/1610612762/2023/02/GettyImages-97245077.jpg (UTA white Feb 2010 vs DAL, sharp Getty but 165px face, looking down at the ball)'
node scripts/portraits/select-source.js --slug shawn-kemp --url 'https://cdn.nba.com/manage/2025/05/GettyImages-1397818sk.jpg' --page 'https://www.nba.com/news/most-rebounds-in-a-playoff-game-oklahoma-city-thunder' --license 'unknown (Getty Images / NBAE via NBA.com)' --author 'Getty Images / NBAE' --date '1996-97 (at Denver, McNichols Arena, Sonics won 108-104; gold NBA 50th-anniversary logo on the jersey)' --crop 471,0,957 --scores 2,3,2,2,2,2,1 --energy 5 --vs-mccain 'lower (looking up off-camera and alert, but lips pressed shut, no open-mouth reaction)' --jersey 'SEA green road 1996-97' --concerns 'FLAG: energy 5 (lips pressed, sweaty look-off; no in-band open-mouth frame of him exists on nba.com in the window); film grain. Getty caption starts "Forward Shawn Kemp", so scan-articles.js missed it; added to the sheet by hand' --alt 'https://cdn.nba.com/manage/2020/12/payton-kemp.jpg (SEA green, mouth open listening to Payton, energy 6, but 198px face, Payton’s head inside the crop and likely 1996 Finals, before the window)' --alt 'https://cdn.nba.com/manage/2025/05/GettyImages-849651308-scaled.jpg (SEA green c. 1996, hands on hips neutral look-off, energy 4.5, 259px)'
